{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.logs",
      "severity": "HIGH",
      "explanation": "The S3 bucket lacks an `aws_s3_bucket_public_access_block` resource. Without this, the bucket is susceptible to public access if ACLs or policies are misconfigured, violating security best practices for data protection."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "Access logging is not configured for this bucket. Enabling server access logs is critical for auditing and monitoring who accesses the stored log data, especially since this bucket itself stores logs."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "Ensure that an S3 bucket has a lifecycle configuration",
      "resource": "aws_s3_bucket.logs",
      "severity": "LOW",
      "explanation": "No lifecycle rules are defined. For a log storage bucket, lifecycle configurations are essential to manage retention periods, transition objects to cheaper storage classes (like Glacier), or expire old logs to control costs and meet compliance requirements."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "logs" {
  bucket = "${local.resource_prefix.value}-logs"
  acl    = "log-delivery-write"
  versioning {
    enabled = true
  }
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = "${aws_kms_key.logs_key.arn}"
      }
    }
  }
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-logs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket                  = aws_s3_bucket.logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    id     = "expire-logs"
    status = "Enabled"

    expiration {
      days = 90
    }
  }
}

resource "aws_s3_bucket_logging" "logs" {
  bucket        = aws_s3_bucket.logs.id
  target_bucket = aws_s3_bucket.logs.id
  target_prefix = "access-logs/"
}",
  "fix_summary": "Added `aws_s3_bucket_public_access_block` to prevent unintended public exposure. Added `aws_s3_bucket_logging` to enable access logging for audit trails. Added `aws_s3_bucket_lifecycle_configuration` with a default 90-day expiration rule to manage log retention and cost."
}
